record.field:
# 1. Puantajları Ayırma İşlemi
ucretsiz_gun = 0.0
toplam_puantaj = 0.0
out_gun = 0.0

for code, wd in worked_days.items():
    k = str(code).upper()
    isim = str(wd.work_entry_type_id.name).upper()

    # SÖZLEŞME DIŞI
    if k == 'OUT' or 'SÖZLEŞME' in isim or 'SOZLESME' in isim:
        out_gun += wd.number_of_days
        continue

    # Fazla mesai hariç aktif günler
    if k not in ['MESAI', 'OT', 'OVERTIME']:
        toplam_puantaj += wd.number_of_days

        # Ücretsiz izinleri yakala
        if k in ['LEAVE90', 'UCRETSIZ', 'UNPAID', 'ODENMEMIS'] or 'ÖDENMEMİŞ' in isim or 'ÜCRETSİZ' in isim:
            ucretsiz_gun += wd.number_of_days

# 2. HAM MAAŞI ÇEK
maas = 0.0
try:
    if payslip.version_id:
        maas = payslip.version_id.wage
except:
    pass

if maas == 0.0:
    try:
        if payslip.contract_id:
            maas = payslip.contract_id.wage
    except:
        pass

ay_ceken_gun = payslip.date_to.day

# 3. KIST AY MATEMATİĞİ
if out_gun == 0 and toplam_puantaj >= ay_ceken_gun:
    odenecek_gun = 30.0 - ucretsiz_gun
else:
    odenecek_gun = toplam_puantaj - ucretsiz_gun

if odenecek_gun > 30.0:
    odenecek_gun = 30.0
if odenecek_gun < 0.0:
    odenecek_gun = 0.0

if odenecek_gun > 0:
    result = (maas / 30.0) * odenecek_gun
else:
    result = 0.0

mesai_saat = 0.0
if 'OVERTIME' in worked_days:
    mesai_saat = worked_days['OVERTIME'].number_of_hours

if mesai_saat > 0:
    maas = 0.0
    try:
        if payslip.version_id:
            maas = payslip.version_id.wage
    except:
        pass
    if maas == 0.0:
        try:
            if payslip.contract_id:
                maas = payslip.contract_id.wage
        except:
            pass
    saatlik_ucret = (maas / 30.0) / 7.5
    result = mesai_saat * saatlik_ucret * 1.5
else:
    result = 0.0

try:
    sgk_matrahi = categories['BASIC']

    yol_parasi = 0.0
    try:
        if 'WORK100' in worked_days and payslip.version_id:
            yol_parasi = worked_days['WORK100'].number_of_days * payslip.version_id.yol_yardim_ucreti
    except:
        pass

    mesai_parasi = 0.0
    try:
        if 'OVERTIME' in worked_days:
            mesai_saati = worked_days['OVERTIME'].number_of_hours
            if mesai_saati > 0:
                maas = payslip.version_id.wage if payslip.version_id else (payslip.contract_id.wage if payslip.contract_id else 0.0)
                if maas > 0:
                    saatlik_ucret = (maas / 30.0) / 7.5
                    mesai_parasi = mesai_saati * saatlik_ucret * 1.5
    except:
        pass

    istisna_asan_yemek = 0.0
    try:
        if 'WORK100' in worked_days and payslip.version_id:
            yemek_parasi = worked_days['WORK100'].number_of_days * payslip.version_id.yemek_yardim_ucreti
            if yemek_parasi > 0:
                try:
                    aylik_asgari_brut = payslip._rule_parameter('l10n_tr_gross_min_wage')
                except:
                    aylik_asgari_brut = 20002.50
                gunluk_istisna = (aylik_asgari_brut / 30.0) * 0.2365
                toplam_istisna = gunluk_istisna * worked_days['WORK100'].number_of_days
                if yemek_parasi > toplam_istisna:
                    istisna_asan_yemek = yemek_parasi - toplam_istisna
    except:
        pass

    sgk_matrahi += mesai_parasi + yol_parasi + istisna_asan_yemek
except:
    sgk_matrahi = 0.0

result_base = min(sgk_matrahi, payslip._rule_parameter('l10n_tr_ssi_base_ceiling'))

kanun_no = '00000'
if payslip.version_id:
    kanun_no = payslip.version_id.sgk_kanun_no

if kanun_no == '05510':
    result = result_base * 0.05
elif kanun_no == '06111':
    result = result_base * 0.205
elif kanun_no == '05746':
    result = result_base * 0.1025
else:
    result = 0.0
